<template>
  <v-container fluid class="pa-0">
    <v-row justify="center" class="ma-0">
      <v-col cols="12" sm="10" md="8" lg="6" xl="4" class="pa-0">
        <div class="content-wrapper">
          <!-- Header Section -->
          <v-row class="ma-0">
            <v-col cols="12" class="pa-0">
              <div class="header">
                <h1 class="header-title">Yangi topshiriq</h1>
              </div>
            </v-col>
          </v-row>
          
          <!-- Form Section -->
          <v-row class="ma-0 form-section">
            <v-col cols="12" class="pa-4">
              <v-form class="task-form" @submit.prevent="createTask">
                <!-- Assignee Selection -->
                <div class="form-field">
                  <v-select 
                    v-model="formData.user_id" 
                    :items="task_members" 
                    label="Kimga" 
                    item-title="name" 
                    item-value="user_id"
                    clearable 
                    color="primary" 
                    variant="solo" 
                    density="compact"
                    :class="{'mobile-field': $vuetify.display.mobile}"
                  ></v-select>
                </div>

                <!-- Members -->
                <div class="form-field">
                  <v-text-field 
                    v-model="formData.members"
                    label="Kimlarga" 
                    
                    clearable 
                    color="primary" 
                    variant="solo" 
                    density="compact"
                    :class="{'mobile-field': $vuetify.display.mobile}"
                  ></v-text-field>
                </div>
                <!-- Task Name -->
                <div class="form-field">
                  <v-text-field 
                    v-model="formData.task_name"
                    label="Nomi" 
                    required 
                    clearable 
                    color="primary" 
                    variant="solo" 
                    density="compact"
                    :class="{'mobile-field': $vuetify.display.mobile}"
                  ></v-text-field>
                </div>

                <!-- Additional Info -->
                <div class="form-field">
                  <v-text-field 
                    v-model="formData.task_description"
                    label="Qo'shimcha" 
                    required 
                    clearable 
                    color="primary" 
                    variant="solo" 
                    density="compact"
                    :class="{'mobile-field': $vuetify.display.mobile}"
                  ></v-text-field>
                </div>

                <!-- Status -->
                <div class="form-field">
                  <v-select 
                    v-model="formData.status"
                    :items="statusOptions"
                    label="Status" 
                    required 
                    clearable 
                    color="primary" 
                    variant="solo" 
                    density="compact"
                    :class="{'mobile-field': $vuetify.display.mobile}"
                  ></v-select>
                </div>

                <!-- Deadline -->
                <div class="form-field">
                  <v-text-field 
                    v-model="formData.task_deadline"
                    label="Muddati" 
                    type="date" 
                    required 
                    clearable 
                    color="primary" 
                    variant="solo" 
                    density="compact"
                    :class="{'mobile-field': $vuetify.display.mobile}"
                  ></v-text-field>
                </div>
                <!-- Deadline -->
                <div class="form-field">
                  <v-text-field 
                    v-model="formData.project_id"
                    label="Project id" 
                     
                    required 
                    clearable 
                    color="primary" 
                    variant="solo" 
                    density="compact"
                    :class="{'mobile-field': $vuetify.display.mobile}"
                  ></v-text-field>
                </div>

                <!-- Submit Button -->
                <div class="button-container">
                  <v-btn 
                    color="primary" 
                    :block="$vuetify.display.mobile"
                    :size="$vuetify.display.mobile ? 'large' : 'default'"
                    class="submit-btn"
                    type="submit"
                    :loading="loading"
                  >
                    Yaratish
                  </v-btn>
                </div>
              </v-form>
            </v-col>
          </v-row>
        </div>
      </v-col>
    </v-row>
  </v-container>
</template>


<script setup>
import axios from 'axios';
import {  ref } from 'vue';

// const members = ref([]);
const loading = ref(false);

// Form data object
const formData = ref({
  user_id: '',
  members: null,
  task_name: '',
  task_description: '',
  task_deadline: '',
  project_id: ''
});

// Status options
const statusOptions = ref([
  { title: 'Yangi', value: 'Yangi' },
  { title: 'Jarayonda', value: 'Jarayonda' },
  { title: 'Tekshirishda', value: 'Tekshirishda' },
  { title: 'Yakunlangan', value: 'Yakunlangan' }
]);

const task_members = ref([
        {
            "user_id": 5,
            "name": "Furqatbek"
        },
        {
            "user_id": 13,
            "name": "Ibrohimjon"
        },
        {
            "user_id": 14,
            "name": "Ravshanbek"
        },
        {
            "user_id": 15,
            "name": "Azizbek"
        },
        {
            "user_id": 22,
            "name": "Shoxabbos"
        },
        {
            "user_id": 23,
            "name": "Mirolim"
        },
        {
            "user_id": 24,
            "name": "Ahadbek"
        }
    ])

// onMounted(async () => {
//   try {
//     const response = await axios.get("http://10.142.62.135/api/tasks/");
//     members.value = response.data.task_members;
//     // console.log(members.value)
//   } catch (error) {
//     console.error('Xatolik yuz berdi:', error);
//   }
// });

async function createTask() {
  // Validation
  if (!formData.value.user_id || !formData.value.task_name || !formData.value.task_deadline) {
    alert('Iltimos, barcha majburiy maydonlarni to\'ldiring');
    return;
  }

  loading.value = true;
  
  try {
    const response = await axios.post("http://10.142.62.135//api/task-create/", formData.value);

    console.log('Topshiriq muvaffaqiyatli yaratildi:', response.data);
    
    // Reset form after successful creation
    resetForm();
    
    // Show success message (you can replace this with a proper notification)
    alert('Topshiriq muvaffaqiyatli yaratildi!');
    
  } catch (error) {
    console.error('Topshiriq yaratishda xatolik:', error);
    alert('Topshiriq yaratishda xatolik yuz berdi. Iltimos, qaytadan urinib ko\'ring.');
  } finally {
    loading.value = false;
  }
}

function resetForm() {
  formData.value = {
    user_id: null,
    name: '',
    description: '',
    status: '',
    deadline: ''
  };
}
</script>
<style scoped>
