  margin-bottom: 16px;
}

/* Button container */
.button-container {
  display: flex;
  justify-content: center;
  margin-top: 24px;
}

.submit-btn {
  min-width: 120px;
  text-transform: none;
  font-weight: 600;
}

/* Mobile specific styles */
.mobile-field {
