  }
  
  .header-title {
    font-size: 1.25rem;
  }
  
  .form-field {
    margin-bottom: 12px;
  }
  
  .button-container {
    margin-top: 20px;
  }
  
  .submit-btn {
    min-width: 100%;
  }
}

@media (max-width: 400px) {
  .header-title {
    font-size: 1.1rem;
  }
  
  .content-wrapper {
    margin: 4px;
    border-radius: 8px;
  }
}

/* Large screen adjustments */
@media (min-width: 1200px) {
  .content-wrapper {
    max-width: 450px;
  }
}

/* Tablet adjustments */
@media (min-width: 768px) and (max-width: 1024px) {
  .content-wrapper {
    max-width: 400px;
  }
}

/* Height adjustments for very small screens */
