  .content-wrapper {
    max-height: 90vh;
    overflow-y: auto;
  }
}

/* Form field focus improvements */
:deep(.v-field--focused) {
  border-color: #00bcd4 !important;
}

/* Loading state improvements */
:deep(.v-btn--loading) {
  opacity: 0.8;
}
</style>